# test cross-divider support
def transform(grid):
    from collections import Counter
    g=[r[:] for r in grid]; H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    rowd=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=bg]
    cold=[c for c in range(W) if len(set(g[r][c] for r in range(H)))==1 and g[0][c]!=bg]
    out=[r[:] for r in g]
    if rowd and cold:
        rd,cd=rowd[0],cold[0]
        P=[r[:cd] for r in g[:rd]]
        for r in range(H):
            if r==rd: out[r]=[g[rd][0]]*W
            else:
                i=r if r<rd else r-rd-1
                out[r]=P[i][:]+[g[0][cd]]+P[i][:]
        return out
    if rowd:
        rd=rowd[0]
        regions=[]; prev=0
        for r in rowd+[H]:
            if r>prev: regions.append((prev,r))
            prev=r+1
        sc=lambda a,b: sum(1 for r in range(a,b) for c in range(W) if g[r][c]!=bg)
        cont=max(regions,key=lambda t:sc(*t)); Pa=g[cont[0]:cont[1]]; h=cont[1]-cont[0]
        for a,b in regions:
            if (a,b)!=cont:
                for i,r in enumerate(range(a,b)): out[r]=Pa[i%h][:]
        return out
    if cold:
        cd=cold[0]
        regions=[]; prev=0
        for c in cold+[W]:
            if c>prev: regions.append((prev,c))
            prev=c+1
        sc=lambda a,b: sum(1 for c in range(a,b) for r in range(H) if g[r][c]!=bg)
        cont=max(regions,key=lambda t:sc(*t)); w=cont[1]-cont[0]
        for a,b in regions:
            if (a,b)!=cont:
                for r in range(H):
                    for i,c in enumerate(range(a,b)): out[r][c]=g[r][cont[0]+(i%w)]
    return out
